import { useNavigate } from 'react-router-dom';
import React, { useState, useEffect, useContext } from "react";
import { AuthContext } from "../context/authContext";
import api from "../services/api";
import { API_ENDPOINTS } from "../services/apiEndpoints";
import WallForm from "../components/walls/wallForm";
import TweetForm from "../components/walls/tweetForm";
import TweetList from "../components/walls/tweetList";

const Dashboard = () => {
  const navigate = useNavigate();
  const logoUrl = '/path-to-logo.png'; // Replace with actual logo URL or fetch from user profile

  const handleLogout = () => {
    // Logout logic here
    navigate('/login');
  };

  return (
    <div className="p-6">
      {/* Updated Header */}
      <div className="flex justify-between items-center mb-6">
        <div className="flex items-center">
          <img src={logoUrl} alt="Logo" className="w-10 h-10 mr-2 rounded-full" />
          <h2 className="text-2xl font-bold">Abhi's Wall</h2>
        </div>
        <div className="space-x-4">
          <button
            onClick={() => navigate('/create-wall')}
            className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600"
          >
            Create Wall
          </button>
          <button
            onClick={() => navigate('/profile')}
            className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600"
          >
            Profile
          </button>
          <button
            onClick={handleLogout}
            className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600"
          >
            Logout
          </button>
        </div>
      </div>
      {/* Rest of the dashboard (wall cards) */}
    </div>
  );
};

export default Dashboard;
